const body = $input.item.json;
const audioUrl = body.audioUrl || body.audio_url || body.fileUrl || body.file_url || body.url;
const transcript = body.transcript || body.text || body.transcript_text || '';
return [{ json: { audioUrl, transcript, originalBody: body } }];

const item = $input.item.json;
if (item.transcript) {
  return [{ json: item }];
}
if (!item.audioUrl) {
  throw new Error('Please provide either transcript or audioUrl/audio_url/fileUrl/file_url.');
}
const transcriptionUrl = $env.TRANSCRIPTION_API_URL || 'http://localhost:11434/v1/audio/transcriptions';
const apiKey = $env.API_KEY || '';
const response = await this.helpers.request({
  method: 'POST',
  uri: transcriptionUrl,
  json: true,
  headers: { Authorization: `Bearer ${apiKey}` },
  body: { audio_url: item.audioUrl, language: 'fa', response_format: 'text' }
});
const transcript = typeof response === 'string' ? response : response.text || response.transcript || response.data || JSON.stringify(response);
return [{ json: { ...item, transcript } }];

const aiResponse = $input.item.json;
let text = '';
if (aiResponse.choices?.[0]?.message?.content) text = aiResponse.choices[0].message.content;
else if (aiResponse.choices?.[0]?.text) text = aiResponse.choices[0].text;
else if (typeof aiResponse === 'string') text = aiResponse;
else text = JSON.stringify(aiResponse);
let parsed;
try { parsed = JSON.parse(text); } catch (error) { parsed = { raw_text: text }; }
return [{ json: { analysis: parsed, raw: aiResponse } }];
